// withImageLoading.jsx
import React, { useState, useEffect } from "react";

// Animated loading text component
const LoadingText = ({ text = "Loading", interval = 400 }) => {
  const [displayText, setDisplayText] = useState("");

  useEffect(() => {
    let index = 0;
    const fullText = text + "...";
    const timer = setInterval(() => {
      setDisplayText(fullText.slice(0, index + 1));
      index++;
      if (index > fullText.length) index = 0;
    }, interval);

    return () => clearInterval(timer);
  }, [text, interval]);

  return (
    <div style={{ textAlign: "center", padding: "20px", fontFamily: "Arial, sans-serif", fontSize: "16px" }}>
      {displayText}
    </div>
  );
};

// HOC for image loading
const withImageLoading = (WrappedComponent) => {
  return ({ src, ...props }) => {
    const [loading, setLoading] = useState(true);
    const [imageSrc, setImageSrc] = useState(null);

    useEffect(() => {
      if (!src) return;
      setLoading(true);
      const img = new Image();
      img.src = src;
      img.onload = () => {
        setImageSrc(src);
        setLoading(false);
      };
      img.onerror = () => setLoading(false);

      return () => {
        img.onload = null;
        img.onerror = null;
      };
    }, [src]);

    if (loading) {
      return <LoadingText />;
    }

    return <WrappedComponent {...props} src={imageSrc} />;
  };
};

export default withImageLoading;
